const button = document.createElement("button");
button.textContent = "Like";
document.body.append(button);

let likes = 0;
button.addEventListener("click", () => {
  likes++;
  button.textContent = `Like (${likes})`;
  console.log(`Clicked ${likes} time(s)`);
});

button.click();   // simulate two clicks
button.click();
console.log(button.textContent);

const input = document.createElement("input");
document.body.append(input);

input.addEventListener("input", (event) => {
  console.log(`type: ${event.type}, value: ${event.target.value}`);
});

input.value = "hi";
input.dispatchEvent(new Event("input"));

document.addEventListener("keydown", (event) => {
  console.log(`key: ${event.key}`);
});
document.dispatchEvent(new KeyboardEvent("keydown", { key: "Enter" }));

const form = document.createElement("form");
form.innerHTML = '<input name="q" value="dom"><button>Search</button>';
document.body.append(form);

form.addEventListener("submit", (event) => {
  event.preventDefault();                 // stop the page from reloading
  const data = new FormData(form);
  console.log(`Searching for ${data.get("q")}`);
});
form.requestSubmit();

const once = document.createElement("button");
once.addEventListener("click", () => console.log("only once"), { once: true });
once.click();
once.click();

function report() {
  console.log("reported");
}
once.addEventListener("click", report);
once.removeEventListener("click", report);
once.click();
console.log("end");

const list = document.createElement("ul");
list.innerHTML = "<li>Apples</li><li>Pears</li>";
document.body.append(list);

list.addEventListener("click", (event) => {
  const item = event.target.closest("li");
  if (!item) return;                        // click on the list itself, not an item
  console.log(`You picked ${item.textContent}`);
});

list.querySelectorAll("li")[1].click();
list.querySelector("li").click();

const plums = document.createElement("li");
plums.textContent = "Plums";
list.append(plums);                         // added after the listener
plums.click();
